function preferenceScore(key,value,a){switch(key){case'space':return ({small:{small:5,medium:3,large:1},medium:{small:4,medium:5,large:2},large:{small:3,medium:4,large:5}})[value][a.space];case'budget':return 5-Math.abs(({low:1,medium:2,high:3})[value]-scale[a.cost])*1.7;case'time':return ({low:{low:5,medium:3,high:1},medium:{low:3,medium:5,high:2},high:{low:2,medium:4,high:5}})[value][a.time];case'noise':return ({low:{none:5,low:5,medium:3,high:1},medium:{none:3,low:4,medium:5,high:2},high:{none:2,low:3,medium:4,high:5}})[value][a.noise];case'experience':return value==='beginner'?({easy:5,medium:3,hard:1})[a.difficulty]:({easy:3,medium:4,hard:5})[a.difficulty];case'care':return value==='easy'?({easy:5,medium:3,hard:1})[a.care]:({easy:3,medium:4,hard:5})[a.care];case'character':return (value==='social')===(a.character==='social')?5:3;default:return 3}}
