 if(intent==='health'){const name=animal?` ${escapeHtml(animal.name)}`:'';const openings=animal?[`Aku ikut prihatin melihat kondisi${name}.`,`Aduh, semoga${name} segera mendapat bantuan yang tepat.`,`Pasti mengkhawatirkan melihat perubahan pada${name}.`]:['Aku ikut prihatin mendengarnya.','Aduh, semoga hewanmu segera mendapat bantuan yang tepat.','Pasti mengkhawatirkan melihat kondisi seperti itu.'];sendBotHtml(`${varyReply('health',openings)} Aku tidak bisa memastikan penyebab gejala dari chat. Sulit bernapas, perdarahan, kejang, keracunan, kondisi yang memburuk, atau muntah berulang perlu segera ditangani dokter hewan. Kalau kamu mau, ceritakan gejala dan kapan mulai terjadi; aku bisa bantu menyusun informasi untuk disampaikan ke klinik.`);return;}
 const ex=extractPreferences(text);state.preferences=ex.preferences;state.sessionParameters={...state.preferences};let html='';
