 if(intent==='recommendation'||intent==='characteristic'||intent==='unknown'&&Object.keys(state.preferences).length){const readiness=confidence(text,intent,ex.found),required=['space','budget','time','experience'],missing=required.filter(k=>state.preferences[k]==null);if(readiness<70||missing.length){const labels={space:'ruang/tempat tinggal',budget:'anggaran',time:'waktu luang per hari',experience:'pengalaman merawat hewan'};sendBotHtml(`Aku sudah menangkap ${Object.keys(state.preferences).length} kebutuhanmu, tapi informasinya belum cukup untuk membuat rekomendasi yang adil. Boleh ceritakan ${missing.map(k=>labels[k]).join(', ')||'satu atau dua kebutuhan lain'}? Jawab santai saja, boleh sekaligus.`);return;}const rank=rankAnimals(state.preferences);state.lastRecommendations=rank;state.lastConfidence=readiness;const detected=Object.entries(state.preferences).map(([k,v])=>`<span class="reason-tag">${weightLabels[k]}: ${preferenceLabel(k,v)}</span>`).join('');html=`${varyReply('recommendation',['Dari ceritamu, aku menangkap beberapa hal ini:','Oke, aku sudah mencatat kebutuhan yang kamu sebutkan:','Dengan mempertimbangkan ceritamu, ini kecocokan awal yang kutemukan:'])} <div class="reason-list">${detected}</div>Aku sudah mencocokkannya dengan profil ${animals.length} hewan. Skor mempertimbangkan faktor yang kamu ceritakan dan menetralkan hal yang belum diketahui. Kamu bisa buka “Lihat langkah penalaran” untuk melihat pertimbangannya. Anggap hasilnya titik awal untuk riset, ya—setiap hewan tetap punya kebutuhan khusus.`;sendBotHtml(html);return;}
 if(intent==='comparison'&&comparisonHits.length>=2){const [a,b]=comparisonHits;html=`<b>${a.name} dan ${b.name}</b><br>Ruang: ${a.space} vs ${b.space} · Perawatan: ${a.care} vs ${b.care} · Biaya: ${a.cost} vs ${b.cost} · Perkiraan umur: ${a.lifespan} vs ${b.lifespan}.<br><br>Catatan kesejahteraan: ${escapeHtml(a.cons?.[0]||'Periksa kebutuhan spesies secara khusus.')} untuk ${a.name}; ${escapeHtml(b.cons?.[0]||'Periksa kebutuhan spesies secara khusus.')} untuk ${b.name}. Ini perbandingan awal berdasarkan profil lokal.`;}
